mapper.select:
SELECT S.SCHEDULE_ID, S.SCHEDULE_NM, S.DIAG_TYPE, S.DATA_MODEL_ID, DM.DM_NM AS DATA_MODEL_NM, S.SCHEDULE_TYPE, S.REPEAT_CYCLE, S.REPEAT_TIME, S.REPEAT_DAY_OF_WEEK, S.REPEAT_DAY_OF_MONTH, S.CRON_EXPR, S.USE_YN, S.LAST_EXEC_DT, S.LAST_EXEC_STATUS, S.LAST_EXEC_LOG_ID, S.CRET_USER_ID, S.CRET_DT, S.UPDT_USER_ID, S.UPDT_DT FROM TB_DIAG_SCHEDULE S LEFT JOIN TB_DATA_MODEL DM ON DM.DM_ID = S.DATA_MODEL_ID
AND S.DATA_MODEL_ID = #{dataModelId}
AND S.DIAG_TYPE = #{diagType}
AND S.USE_YN = #{useYn}
ORDER BY S.CRET_DT DESC

mapper.update:
UPDATE TB_DIAG_SCHEDULE
   SET LAST_EXEC_DT     = CURRENT_TIMESTAMP,
       LAST_EXEC_STATUS = #{status},
       LAST_EXEC_LOG_ID = #{logId}
 WHERE SCHEDULE_ID = #{scheduleId}

mapper.select:
SELECT COUNT(1) FROM TB_DIAG_SCHEDULE_LOG L
  JOIN TB_DIAG_SCHEDULE S ON S.SCHEDULE_ID = L.SCHEDULE_ID
 WHERE S.DATA_MODEL_ID = #{dataModelId}
   AND L.DIAG_TYPE     = #{diagType}
   AND L.EXEC_STATUS   = 'RUNNING'

SELECT L.LOG_ID, L.SCHEDULE_ID, L.SCHEDULE_NM_SNAPSHOT, L.EXEC_DT, L.EXEC_END_DT, L.EXEC_STATUS, L.TRIGGER_TYPE, L.DIAG_TYPE, L.DIAG_JOB_ID, L.STRUCT_DIAG_ID, L.ERROR_MSG, L.EXEC_DURATION_SEC FROM TB_DIAG_SCHEDULE_LOG L
AND L.SCHEDULE_ID = #{scheduleId}
AND L.EXEC_STATUS = #{execStatus}
AND L.EXEC_DT >= #{fromDt}::timestamp
AND L.EXEC_DT <= #{toDt}::timestamp
ORDER BY L.EXEC_DT DESC LIMIT COALESCE(#{limit}, 200)

mapper.insert:
INSERT INTO TB_DIAG_SCHEDULE_LOG (
    LOG_ID, SCHEDULE_ID, SCHEDULE_NM_SNAPSHOT,
    EXEC_DT, EXEC_STATUS, TRIGGER_TYPE,
    DIAG_TYPE, DIAG_JOB_ID, STRUCT_DIAG_ID
) VALUES (
    #{logId}, #{scheduleId}, #{scheduleNmSnapshot},
    CURRENT_TIMESTAMP, COALESCE(#{execStatus}, 'RUNNING'), #{triggerType},
    #{diagType}, #{diagJobId}, #{structDiagId}
)

mapper.update:
UPDATE TB_DIAG_SCHEDULE_LOG
   SET DIAG_JOB_ID = #{diagJobId}
 WHERE LOG_ID = #{logId}

UPDATE TB_DIAG_SCHEDULE_LOG
   SET STRUCT_DIAG_ID = #{structDiagId}
 WHERE LOG_ID = #{logId}
